mapper.insert:
 		INSERT INTO SYS_AUTH_GRP_INFO_TBL (
			AUTH_GRP_CD
		  , AUTH_GRP_TP
		  , USE_YN
		  , AUTH_GRP_NM
		  , AUTH_GRP_DESC	
		  , RGST_DT
		  , RGST_SEQ
		)
		VALUES (
			#{authGrpCd, jdbcType=VARCHAR}
		  , 	#{authGrpTp, jdbcType=VARCHAR}
 		  , 	( 
				CASE
					WHEN (#{useYn, jdbcType=VARCHAR} IS NULL OR #{useYn, jdbcType=VARCHAR} = '') THEN 'Y'
					ELSE    #{useYn, jdbcType=VARCHAR}
				END
			)	
 		  , 	#{authGrpNm, jdbcType=VARCHAR}
 		  , #{authGrpDesc, jdbcType=VARCHAR}
 		  , CURRENT_TIMESTAMP(3)
 		  , #{rgstSeq, jdbcType=NUMERIC}
		)

mapper.update:
 		UPDATE SYS_AUTH_GRP_INFO_TBL
 		SET 	AUTH_GRP_TP = 	(
					CASE
						WHEN (#{authGrpTp, jdbcType=VARCHAR} IS NULL OR #{authGrpTp, jdbcType=VARCHAR} = '') THEN AUTH_GRP_TP
						ELSE   #{authGrpTp, jdbcType=VARCHAR} 
					END
				)
			  , USE_YN  = (
					CASE
						WHEN (#{useYn, jdbcType=VARCHAR} IS NULL OR #{useYn, jdbcType=VARCHAR} = '') THEN USE_YN 
						ELSE   #{useYn, jdbcType=VARCHAR}
					END
			   )
			  , AUTH_GRP_NM = (
					CASE
						WHEN (#{authGrpNm, jdbcType=VARCHAR} IS NULL OR #{authGrpNm, jdbcType=VARCHAR} = '') THEN AUTH_GRP_NM
						ELSE   #{authGrpNm, jdbcType=VARCHAR}
					END
			   )
			  , AUTH_GRP_DESC = (
					CASE
						WHEN (#{authGrpDesc, jdbcType=VARCHAR} IS NULL OR #{authGrpDesc, jdbcType=VARCHAR} = '') THEN AUTH_GRP_DESC
						ELSE   #{authGrpDesc, jdbcType=VARCHAR}
					END
			   )
			  , UPDT_DT = CURRENT_TIMESTAMP(3)
			  , UPDT_SEQ = #{updtSeq, jdbcType=NUMERIC}     	
 		WHERE 	1 	= 	1
 		AND 		(((#{authGrpSeq, jdbcType=NUMERIC} IS NULL) OR (#{authGrpSeq, jdbcType=NUMERIC} = 0)) OR (AUTH_GRP_SEQ = #{authGrpSeq, jdbcType=NUMERIC}))
 		AND 		(((#{authGrpCd, jdbcType=VARCHAR} IS NULL) OR (#{authGrpCd, jdbcType=VARCHAR} = '')) OR (AUTH_GRP_CD = #{authGrpCd, jdbcType=VARCHAR}))
